-- Bloco 3/10: 10 perguntas de O Que é o Espiritismo.
-- Seguro para executar individualmente; não altera perguntas existentes.
INSERT INTO public.questions
  (book, statement, option_a, option_b, option_c, option_d, option_e,
   correct_option, explanation, reference, difficulty, active)
VALUES
  ('''o_que_e_espiritismo''', 'No início do Segundo Diálogo (''O Cético''), como o espírita recebe a declaração do Visitante de que não crê nos Espíritos, mas deseja compreender a questão?', 'Com simpatia e respeito, pois a dúvida sincera de quem procura instruir-se merece explicação racional.', 'Com indignação, recusando-se a conversar com quem ainda não tem fé.', 'Exigindo que o visitante faça antes um juramento de adesão religiosa.', 'Cobrando uma taxa de matrícula no curso preparatório da Sociedade.', 'Aconselhando-o a desistir, pois a fé espírita só se obtém por graça mística.', 'A', 'Kardec acolhe o Cético com estima, esclarecendo que o Espiritismo não exige fé cega, mas convida ao exame sério, metódico e livre de ideias preconcebidas.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'facil', true),
  ('''o_que_e_espiritismo''', 'No Segundo Diálogo (''O Cético''), como Allan Kardec define de modo claro e direto o que são os Espíritos?', 'São seres angélicos criados à parte da humanidade e que jamais encarnaram.', 'São as próprias almas dos homens que viveram na Terra ou em outros mundos, despojadas de seu envoltório corporal.', 'São emanações magnéticas inconscientes produzidas pelo cérebro dos médiuns.', 'São divindades secundárias encarregadas de governar as forças da natureza.', 'São alucinações coletivas provocadas pelo fluido nervoso dos assistentes.', 'B', 'Kardec explica ao Cético que os Espíritos não são seres abstratos nem uma criação nova: são simplesmente as almas dos homens após a morte do corpo físico.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'facil', true),
  ('''o_que_e_espiritismo''', 'Para demonstrar ao Cético a existência da alma independente da matéria, que argumento fundamental o espírita utiliza?', 'A tradição mitológica dos povos gregos e romanos.', 'A autoridade infalível dos concílios medievais.', 'O fato de que o pensamento, a vontade e o livre-arbítrio são propriedades inteligentes que não podem ser produzidas pela matéria bruta.', 'A semelhança anatômica entre o sistema nervoso humano e o dos vegetais.', 'O cálculo matemático da distância entre as estrelas fixas.', 'C', 'Todo efeito inteligente há de ter uma causa inteligente; como a matéria por si mesma é inerte e desprovida de inteligência, o pensamento humano prova a presença de um princípio espiritual.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'expert', true),
  ('''o_que_e_espiritismo''', 'Segundo explica Kardec ao Cético, de quantos elementos essenciais se compõe o homem encarnado?', 'De dois elementos apenas: o corpo carnal e o fluido elétrico.', 'De quatro elementos: terra, água, ar e fogo.', 'De um único elemento material capaz de produzir o pensamento.', 'De três elementos: o corpo (ser material), a alma (Espírito encarnado) e o perispírito (envoltório semimaterial que une a alma ao corpo).', 'De cinco corpos astrais independentes entre si.', 'D', 'Kardec apresenta a constituição ternária do homem: 1º o corpo físico; 2º a alma ou Espírito; 3º o perispírito, laço fluídico semimaterial que serve de intermediário entre ambos.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'facil', true),
  ('''o_que_e_espiritismo''', 'Quando o Cético pergunta por que uma mesa se move ou responde por pancadas nas sessões de efeitos físicos, o que o espírita lhe esclarece?', 'Que a madeira adquire inteligência própria ao ser magnetizada pelos presentes.', 'Que o movimento resulta exclusivamente da eletricidade terrestre acumulada no móvel.', 'Que todos os movimentos de mesas são produzidos por mecanismos ocultos sob o soalho.', 'Que os Espíritos se transformam materialmente na própria estrutura da mesa.', 'Que a mesa é apenas um instrumento passivo movido pelo Espírito, que combina parte de seu perispírito com o fluido animalizado do médium.', 'E', 'A mesa não pensa nem tem músculos: o Espírito utiliza o fluido próprio do médium combinado ao fluido universal e ao seu perispírito para imprimir movimento ao objeto e dar sinais convencionados.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
  ('''o_que_e_espiritismo''', 'No Segundo Diálogo, por que o uso das mesas falantes e das cestas foi gradualmente substituído pela escrita direta com a mão do médium (psicografia)?', 'Porque a escrita manual direta é o meio mais simples, rápido e cômodo de comunicação, dispensando aparelhos acessórios.', 'Porque as mesas deixaram de girar após o ano de 1856 em toda a Europa.', 'Porque a polícia francesa proibiu a fabricação de cestas-pião e pranchetas.', 'Porque os Espíritos Superiores só conseguem se comunicar por meio de mesas pesadas.', 'Porque a escrita direta impede totalmente a manifestação de Espíritos levianos.', 'A', 'As mesas, cestas e pranchetas eram apenas apêndices do lápis; compreendeu-se logo que o Espírito podia atuar diretamente sobre o braço e a mão do médium, tornando a comunicação muito mais rápida.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
  ('''o_que_e_espiritismo''', 'No diálogo com o Cético, qual é a posição do Espiritismo a respeito do Magnetismo e do Sonambulismo?', 'Considera o magnetismo uma superstição medieval sem qualquer base real.', 'Reconhece-os como ciências irmãs que prepararam o caminho ao demonstrar a ação dos fluidos e a independência da alma.', 'Afirma que o magnetizador só cura quando pronuncia fórmulas cabalísticas.', 'Sustenta que todo médium psicógrafo precisa antes ser magnetizado por um médico.', 'Declara que o fluido magnético destrói a faculdade mediúnica.', 'B', 'Kardec explica que o magnetismo preparou o caminho do Espiritismo, pois o estudo do fluido magnético e da clarividência sonambúlica já demonstrava a ação da alma fora dos sentidos corpóreos.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'dificil', true),
  ('''o_que_e_espiritismo''', 'Que fatos comprovam ao Cético que as comunicações mediúnicas não são simples reflexo das ideias do próprio médium?', 'O fato de o médium usar sempre papel timbrado das sociedades espíritas.', 'A velocidade com que o lápis percorre o papel em linha reta.', 'Comunicações contrárias às opiniões e conhecimentos do médium, em línguas que ele ignora ou até por pessoas analfabetas.', 'O cansaço muscular sentido no braço após duas horas de escrita.', 'A presença obrigatória de sete testemunhas diplomadas na sala.', 'C', 'O Espírito frequentemente trata de assuntos estranhos aos estudos do médium, contradiz suas ideias preconcebidas, revela fatos desconhecidos e por vezes escreve em idiomas que o médium desconhece.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'dificil', true),
  ('''o_que_e_espiritismo''', 'Quando o Cético pergunta se basta morrer para que o Espírito saiba tudo e possua toda a sabedoria, o que Kardec responde?', 'Sim, pois a morte rasga imediatamente todos os véus do universo.', 'Sim, desde que o falecido tenha recebido os sacramentos antes de partir.', 'Não, porque após a morte todos os Espíritos perdem a memória para sempre.', 'Não; a morte física não opera transformação miraculosa: o Espírito conserva o grau intelectual e moral que tinha em vida, progredindo gradualmente.', 'Apenas os cientistas conservam a inteligência no mundo espiritual.', 'D', 'Ao deixar o corpo, o homem não se torna instantaneamente sábio nem virtuoso; há no mundo invisível Espíritos de todos os graus de saber e de moralidade.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'facil', true),
  ('''o_que_e_espiritismo''', 'Por que os Espíritos não vêm revelar tesouros ocultos, fórmulas para enriquecer sem trabalho ou invenções prontas para especulação financeira?', 'Porque desconhecem o valor das moedas modernas.', 'Porque estão proibidos de observar a superfície material da Terra.', 'Porque apenas os Espíritos zombeteiros conhecem onde estão os tesouros.', 'Porque perderam toda a capacidade de raciocínio prático ao desencarnar.', 'Porque a lei de Deus impõe ao homem o progresso pelo trabalho e pela pesquisa própria, e os bons Espíritos não servem à cupidez nem ao orgulho.', 'E', 'Os Espíritos Superiores auxiliam o progresso moral e intelectual da humanidade, mas não poupam ao homem o esforço do trabalho; quem busca os Espíritos por interesse material torna-se joguete de mistificadores.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'expert', true);

SELECT COUNT(*) AS perguntas_do_livro
FROM public.questions
WHERE book = 'o_que_e_espiritismo';